import json
import clr
clr.AddReference('Web.Core.Shared')
from Web.Core.Shared.Services.Endpoints.Engine import WorkflowSessionKeyExecutionContext
session_keys=list(WorkflowSessionKeyExecutionContext.GetKeys(int('${sessionid}')))
def value(name):
    found=[str(k.Value) for k in session_keys if str(k.Key).lower()==name.lower()]
    return found[-1] if found else ''
def obj(name,default=None):
    raw=value(name)
    return json.loads(raw) if raw and raw!='No records found' else default
def snapshot(name='Snapshot'):
    rows=obj(name,[])
    if isinstance(rows,dict):rows=[rows]
    if not rows:raise Exception('Events database could not be loaded.')
    raw=rows[0]['snapshot']
    return json.loads(raw) if isinstance(raw,str) else raw
def request():
    data=obj('body',{})
    if not isinstance(data,dict):raise Exception('Expected a JSON request.')
    return data

"""Events domain. Plans commit under a SQLite revision guard; the server owns prices and admission."""
import copy,json,re,time,uuid
from urllib.parse import urlsplit

def encoded(v):return json.dumps(v,ensure_ascii=False,separators=(',',':'))
def q(v):return "CAST(X'"+str(v).encode('utf8').hex()+"' AS TEXT)"
def require(v,message):
    if not v:raise ValueError(message)
def text(v,limit=500):
    s=str(v or '').strip();require(len(s)<=limit,'Text is too long.');return s
def integer(v,lo=0,hi=100000000):
    require(not isinstance(v,bool),'Enter a whole number.')
    try:n=int(v)
    except (ValueError,TypeError,OverflowError):raise ValueError('Enter a whole number.')
    require(str(n)==str(v) or n==v,'Enter a whole number.');require(lo<=n<=hi,'Number outside allowed range.');return n
def asset(v):
    s=text(v,2048);u=urlsplit(s);local=u.hostname in ('localhost','127.0.0.1','::1') or (u.hostname or '').endswith('.localhost')
    require(not re.search(r'[\s\\<>]',s) and (not s or (s.startswith('/') and not s.startswith('//')) or (u.hostname and not u.username and not u.password and (u.scheme=='https' or (u.scheme=='http' and local)))),'Use an HTTPS URL or local asset path.');return s
def snapshot_sql():return "SELECT json_object('settings',json(COALESCE((SELECT json_group_array(json_object('key',key,'value',value)) FROM settings),'[]')),'entities',json(COALESCE((SELECT json_group_array(json(data)) FROM (SELECT data FROM entities ORDER BY Id LIMIT 20001)),'[]'))) AS snapshot;"

class Engine:
    def __init__(self,snapshot,identity=None,now=None,internal=False):
        self.rows=copy.deepcopy(snapshot.get('entities',[]));require(len(self.rows)<=20000,'Workspace capacity reached. Export and archive history before continuing.')
        self.settings={r['key']:r['value'] for r in snapshot.get('settings',[])};self.user=identity or {};self.now=int(time.time()) if now is None else now;self.internal=internal;self.changed={};self.sql=[]
        self.uid=str(self.user.get('Id') or '') if self.user.get('IsActive') is True else '';self.role=str(self.user.get('Role','')).lower() if self.uid else ''
        if self.role not in ('admin','administrator','owner'):self.role='staff' if self.uid and any(r['user_id']==self.uid and r['active'] for r in self.all('staff')) else 'attendee' if self.uid else ''
    def all(self,kind):return [r for r in self.rows if r['kind']==kind]
    def get(self,ref,kind=None):
        r=next((x for x in self.rows if x['ref']==ref and (not kind or x['kind']==kind)),None);require(r,'Record not found.');return r
