    def admin(self):require(self.isadmin(),'Administrator access required.')
    def admission(self,event):require(self.isadmin() or any(s['user_id']==self.uid and s['active'] and event in s['events'] for s in self.all('staff')),'You are not assigned to this event.')
    def expected(self,r,d):require(d.get('version')==r['version'],'This record changed. Refresh before saving.')
    def save(self,kind,values,old=None):
        r=dict(old or {},**values);r.update(kind=kind,ref=old['ref'] if old else kind[:3].upper()+'-'+uuid.uuid4().hex[:16],version=(old or {}).get('version',0)+1,updated=self.now);r.setdefault('created',self.now);r.setdefault('owner','')
        if old:self.rows[self.rows.index(old)]=r
        else:self.rows.append(r)
        self.changed[r['ref']]=r;return r
    def audit(self,r,action):self.save('audit',dict(entity=r['ref'],action=action,actor=self.uid or 'worker'))
    def public_settings(self):return {k:v for k,v in self.settings.items() if not k.startswith(('_','smtp_'))}
    def mail(self,o,subject,body,key):
        if o.get('email') and not any(x.get('dedupe')==key for x in self.all('message')):self.save('message',dict(recipient=o['email'],subject=subject,body=body,dedupe=key,status='queued',attempts=0,due=self.now))
    def held(self,o):return o['status'] in ('confirmed','review','refunding') or (o['status']=='pending' and (o.get('payment_id') or o['expires']>self.now))
    def used(self,event,tier=None,exclude=None):return sum(o['quantity'] for o in self.all('order') if o['event']==event and (not tier or o['tier']==tier) and o['ref']!=exclude and self.held(o))
    def event_public(self,e):
        tiers=[dict(t,available=max(0,min(t['capacity']-self.used(e['ref'],t['ref']),e['capacity']-self.used(e['ref'])))) for t in self.all('tier') if t['event']==e['ref'] and t['active']]
        return dict(e,tiers=tiers,available=max(0,e['capacity']-self.used(e['ref'])))
    def order(self,ref):
        self.signed();o=self.get(ref,'order');require(o['owner']==self.uid or self.isadmin(),'Record not found.');return o
    def issue(self,o):
        if any(t['order']==o['ref'] for t in self.all('ticket')):return
        e=self.get(o['event'],'event')
        for i in range(o['quantity']):self.save('ticket',dict(order=o['ref'],event=e['ref'],tier=o['tier_name'],title=o['title'],starts=e['starts'],ends=e['ends'],venue=e['venue'],owner=o['owner'],name=o['attendees'][i],email=o['email'],code=uuid.uuid4().hex+uuid.uuid4().hex[:8],status='valid',checked_in=0))
        self.mail(o,'Your tickets for '+o['title'],'Your booking is confirmed. Open My tickets on our website to view your QR admission passes. Booking '+o['ref']+'.','tickets-'+o['ref'])
    def dispatch(self,d):
        op=d.get('op','catalog');require(not op.startswith('_') or self.internal,'Internal operation denied.')
        if op=='catalog':return dict(settings=self.public_settings(),events=[self.event_public(e) for e in self.all('event') if e['status']=='published' and e['ends']>self.now])
        if op=='workspace':
            self.signed();assigned=[e for s in self.all('staff') if s['user_id']==self.uid and s['active'] for e in s['events']];records=[]
            for r in self.rows:
                if self.isadmin():records.append(r)
                elif self.role=='staff' and (r['kind']=='event' and r['ref'] in assigned or r['kind']=='ticket' and r['event'] in assigned):records.append({k:v for k,v in r.items() if k not in ('code','email')})
                elif r.get('owner')==self.uid and r['kind'] in ('order','ticket','waitlist','refund'):records.append({k:v for k,v in r.items() if k not in ('provider','payment_id')})
            return dict(records=records,settings=self.public_settings(),role=self.role,identity=dict(id=self.uid,name=self.user.get('Name',''),email=self.user.get('Email','')),services=[dict(e,name=e['title'],active=e['status']=='published') for e in self.all('event')] if self.isadmin() else [],staff=self.all('staff') if self.isadmin() else [],mediaReferences=[])
        if op=='event-save':
            self.admin();old=self.get(d['ref'],'event') if d.get('ref') else None
            if old:self.expected(old,d);require(old['status']!='cancelled','Cancelled events cannot be edited.')
            title=text(d.get('title'),160);require(title,'Event title is required.');starts=integer(d['starts'],self.now+60,4102444800);ends=integer(d['ends'],starts+60,4102444800);capacity=integer(d.get('capacity'),1,100000)
            require(not old or capacity>=self.used(old['ref']),'Capacity is below current reservations.');currency=text(d.get('currency','USD'),3).upper();require(re.fullmatch('[A-Z]{3}',currency),'Enter a three-letter currency.')
            if old and any(o['event']==old['ref'] for o in self.all('order')):require(currency==old['currency'],'Currency cannot change after reservations.')
            r=self.save('event',dict(title=title,summary=text(d.get('summary'),300),description=text(d.get('description'),12000),category=text(d.get('category','Experiences'),80),venue=text(d.get('venue'),180),address=text(d.get('address'),500),starts=starts,ends=ends,capacity=capacity,currency=currency,image_url=asset(d.get('image_url')),organiser=text(d.get('organiser'),120),refund_policy=text(d.get('refund_policy'),3000),accessibility=text(d.get('accessibility'),2000),status=old['status'] if old else 'draft'),old)
