                for ticket in self.all('ticket'):
                    if ticket['event']==r['ref']:self.save('ticket',dict(title=r['title'],starts=r['starts'],ends=r['ends'],venue=r['venue']),ticket)
                for order in self.all('order'):
                    if order['event']==r['ref'] and order['status'] in ('confirmed','pending'):self.mail(order,'Event details updated: '+r['title'],'The organiser updated the event details. Check the event page and your tickets for the latest time and venue.','event-update-'+order['ref']+'-'+str(r['version']))
            self.audit(r,'event-saved');return r
        if op=='tier-save':
            self.admin();e=self.get(d['event'],'event');require(e['status']!='cancelled','Event cancelled.');old=self.get(d['ref'],'tier') if d.get('ref') else None
            if old:require(old['event']==e['ref'],'Event mismatch.');self.expected(old,d)
            name=text(d.get('name'),100);require(name,'Ticket name is required.');capacity=integer(d['capacity'],1,e['capacity']);require(not old or capacity>=self.used(e['ref'],old['ref']),'Capacity is below current reservations.')
            r=self.save('tier',dict(event=e['ref'],name=name,description=text(d.get('description'),1000),price=integer(d.get('price',0)),capacity=capacity,sale_start=integer(d.get('sale_start',self.now),0,4102444800),sale_end=integer(d.get('sale_end',e['starts']),self.now+1,e['ends']),max_per_order=integer(d.get('max_per_order',6),1,20),active=bool(d.get('active',True))),old);require(r['sale_start']<r['sale_end'],'Sales must end after they start.');self.audit(r,'tier-saved');return r
        if op in ('event-publish','event-archive','event-cancel'):
            self.admin();e=self.get(d['ref'],'event');self.expected(e,d)
            if op=='event-archive':require(e['status']!='cancelled','Cancelled events cannot be reopened.')
            if op=='event-publish':
                require(e['status']!='cancelled' and e['starts']>self.now,'Event cannot be published.');require(e['summary'] and e['description'] and e['venue'] and e['organiser'],'Add summary, description, venue and organiser.');require(any(t['event']==e['ref'] and t['active'] for t in self.all('tier')),'Add an active ticket tier.')
            if op=='event-cancel':
                for t in self.all('ticket'):
                    if t['event']==e['ref'] and t['status']=='valid':self.save('ticket',dict(status='void'),t)
                for o in self.all('order'):
                    if o['event']==e['ref'] and o['status'] in ('confirmed','pending'):self.mail(o,'Event cancelled: '+e['title'],'The organiser cancelled this event. Paid bookings will be reviewed for refunds. Contact the organiser for help.','cancelled-'+o['ref'])
            r=self.save('event',dict(status={'event-publish':'published','event-archive':'archived','event-cancel':'cancelled'}[op]),e);self.audit(r,op);return r
        if op=='reserve':
            self.signed();key=text(d.get('request_key'),96);require(len(key)>=16,'Reservation key is required.');old=next((o for o in self.all('order') if o['owner']==self.uid and o['request_key']==key),None)
            if old:require(old['tier']==d['tier'] and old['quantity']==integer(d['quantity'],1,20),'Reservation key was used for another selection.');return old
            t=self.get(d['tier'],'tier');e=self.get(t['event'],'event');require(e['status']=='published' and e['starts']>self.now and t['active'] and t['sale_start']<=self.now<t['sale_end'],'Ticket sales are closed.');quantity=integer(d.get('quantity'),1,t['max_per_order']);require(self.used(e['ref'])+quantity<=e['capacity'] and self.used(e['ref'],t['ref'])+quantity<=t['capacity'],'Not enough tickets available. Choose fewer tickets.')
            names=d.get('attendees',[]);require(isinstance(names,list) and len(names)==quantity and all(text(n,120) for n in names),'Provide a name for every attendee.');email=text(self.user.get('Email'),256);require(re.fullmatch(r'[^\s@]+@[^\s@]+\.[^\s@]+',email),'Your account needs a valid email address.')
            o=self.save('order',dict(event=e['ref'],tier=t['ref'],tier_name=t['name'],title=e['title'],owner=self.uid,name=text(self.user.get('Name'),120),email=email,attendees=[text(n,120) for n in names],quantity=quantity,amount=quantity*t['price'],currency=e['currency'],request_key=key,status='pending' if t['price'] else 'confirmed',expires=self.now+900))
            if not t['price']:self.issue(o)
            self.audit(o,'reserved');return o
        if op=='order-cancel':
            o=self.order(d['ref']);require(o['status']=='pending' and not o.get('payment_id'),'Only an unpaid reservation without an open checkout can be released.');r=self.save('order',dict(status='cancelled'),o);self.audit(r,'reservation-released');return r
        if op=='waitlist-join':
            self.signed();e=self.get(d['event'],'event');require(e['status']=='published' and e['starts']>self.now,'Event unavailable.');r=next((w for w in self.all('waitlist') if w['event']==e['ref'] and w['owner']==self.uid),None)
            return r or self.save('waitlist',dict(event=e['ref'],title=e['title'],owner=self.uid,name=text(self.user.get('Name'),120),email=text(self.user.get('Email'),256),status='waiting'))
        if op=='waitlist-notify':
