            code=text(d.get('code'),100);t=next((t for t in self.all('ticket') if (t['code']==code or t['ref']==code) and t['event']==e['ref']),None);require(t,'Ticket not found for this event.');require(t['status']=='valid','Ticket is void or refunded.')
            if t['checked_in']:return dict(ok=False,duplicate=True,name=t['name'],checked_in=t['checked_in'],ref=t['ref'])
            r=self.save('ticket',dict(checked_in=self.now,checked_by=self.uid),t);self.audit(r,'checked-in');return dict(ok=True,name=r['name'],tier=r['tier'],ref=r['ref'])
        if op=='check-in-undo':
