        self.changed[r['ref']]=r;return r
    def audit(self,r,action):self.save('audit',dict(entity=r['ref'],action=action,actor=self.uid or 'worker'))
    def public_settings(self):return {k:v for k,v in self.settings.items() if not k.startswith(('_','smtp_'))}
    def mail(self,o,subject,body,key):
