            r=self.save('ticket',dict(checked_in=self.now,checked_by=self.uid),t);self.audit(r,'checked-in');return dict(ok=True,name=r['name'],tier=r['tier'],ref=r['ref'])
        if op=='check-in-undo':
            self.admin();t=self.get(d['ref'],'ticket');self.expected(t,d);r=self.save('ticket',dict(checked_in=0,checked_by=''),t);self.audit(r,'check-in-reversed');return r
        if op=='staff-save':
            self.admin();old=self.get(d['ref'],'staff') if d.get('ref') else None
            if old:self.expected(old,d)
            uid=text(d.get('user_id'),100);name=text(d.get('name'),100);require(uid and name,'Name and Cloudgate user ID are required.');events=d.get('events',[]);require(isinstance(events,list) and len(events)<=100,'Invalid event assignments.')
            for e in events:self.get(e,'event')
            r=self.save('staff',dict(user_id=uid,name=name,events=events,active=bool(d.get('active',True))),old);self.audit(r,'staff-saved');return r
        if op=='settings':
            self.admin()
            for k,v in d.get('values',{}).items():
                if k not in self.public_settings():continue
                v=text(v,12000)
                if k.endswith('_url'):v=asset(v)
                if k.startswith('theme_'):require(re.fullmatch('#[0-9a-fA-F]{6}',v),'Use a six-digit hex colour.')
                self.sql.append('INSERT INTO settings(key,value) VALUES('+q(k)+','+q(v)+') ON CONFLICT(key) DO UPDATE SET value=excluded.value;')
            self.audit(dict(ref='settings'),'settings-saved');return dict(ok=True)
        if op in ('checkout-prepare','payment-prepare','_checkout-save','_payment-apply','refund-prepare','_refund-claim','_refund-apply'):return self.payments(op,d)
        if op=='_mail-claim':
            token=uuid.uuid4().hex;items=[]
            for m in self.all('message'):
                if m['status'] in ('queued','sending') and m.get('due',0)<=self.now and m.get('lease_until',0)<=self.now and m['attempts']<5:
                    items.append(self.save('message',dict(status='sending',lease=token,lease_until=self.now+300,attempts=m['attempts']+1),m))
                    if len(items)==5:break
            return dict(token=token,messages=items)
        if op=='_mail-result':
            for result in d.get('results',[]):
                m=self.get(result['ref'],'message')
                if m.get('lease')!=d.get('token') or m['status']!='sending':continue
                self.save('message',dict(status='sent' if result['sent'] else 'failed' if m['attempts']>=5 else 'queued',lease_until=0,due=self.now+60*2**m['attempts']),m)
            return dict(ok=True)
        raise ValueError('Unknown operation.')

    def payments(self,op,d):
        if op in ('checkout-prepare','payment-prepare','_checkout-save','_payment-apply'):
            o=self.get(d['ref'],'order');e=self.get(o['event'],'event')
            if not self.internal:self.order(o['ref'])
            if op=='checkout-prepare':require(o['status']=='pending' and (o.get('payment_id') or o['expires']>self.now) and e['status']=='published','Reservation expired or no longer payable.');return dict(o,url=self.settings.get('website_url',''))
            if op=='payment-prepare':require(o.get('payment_id'),'Checkout not started.');return o
            if op=='_checkout-save':
                pid=text(d.get('payment_id'),100);url=asset(d.get('payment_url'));require(pid and url.startswith('https://'),'Wallet did not return a secure checkout.');require(not o.get('payment_id') or pid==o['payment_id'],'Checkout identity changed.')
                if o.get('payment_id')==pid:return dict(payment_url=o['payment_url'],ref=o['ref'])
                require(o['status']=='pending','Reservation no longer pending.')
                # A wallet request can outlive the reservation. Keep its identity for reconciliation,
                # but never issue tickets against capacity taken by another reservation.
                review=self.used(e['ref'],exclude=o['ref'])+o['quantity']>e['capacity'] or self.used(e['ref'],o['tier'],o['ref'])+o['quantity']>self.get(o['tier'],'tier')['capacity']
                self.save('order',dict(payment_id=pid,payment_url=url,status='review' if review else 'pending'),o);return dict(payment_url=url,ref=o['ref'])
            p=d.get('provider',{});require(str(p.get('Id'))==o.get('payment_id') and p.get('GrossAmount')==o['amount'] and str(p.get('Currency','')).upper()==o['currency'],'Wallet payment details do not match.')
            if o['status'] in ('confirmed','refunding','refunded'):return dict(status='succeeded',ref=o['ref'])
            if p.get('Status') in (2,3) and not o.get('paid'):
                status='failed' if p['Status']==2 else 'expired';self.save('order',dict(status=status,last_checked=self.now),o);self.audit(o,'payment-'+status);return dict(status=status,ref=o['ref'])
            if p.get('Status')!=1:self.save('order',dict(last_checked=self.now),o);return dict(status='pending',ref=o['ref'])
            review=o['status'] in ('review','failed','expired','cancelled') or e['status']=='cancelled' or self.now>e['ends']
            r=self.save('order',dict(status='review' if review else 'confirmed',paid=self.now,last_checked=self.now),o)
            if not review:self.issue(r)
            else:self.mail(r,'Your booking needs organiser review','Payment was received, but tickets could not be issued. The organiser will review your booking '+r['ref']+'.','review-'+r['ref'])
            self.audit(r,'payment-verified');return dict(status='review' if review else 'succeeded',ref=r['ref'])
        if op=='refund-prepare':
            self.admin();o=self.get(d['ref'],'order');key=text(d.get('request_key'),96);require(len(key)>=16,'Refund key is required.');existing=next((r for r in self.all('refund') if r['request_key']==key),None)
            if existing:require(existing['order']==o['ref'],'Refund key mismatch.');return existing
            require(o.get('paid') and o['status'] in ('confirmed','review'),'Only verified payments can be refunded.');require(not any(t['order']==o['ref'] and t['checked_in'] for t in self.all('ticket')),'Reverse check-in before refunding an admitted ticket.');require(not any(r['order']==o['ref'] and r['status']!='failed' for r in self.all('refund')),'A refund already exists.');return dict(order=o['ref'],payment_id=o['payment_id'],owner=o['owner'],amount=o['amount'],currency=o['currency'],request_key=key,previous_status=o['status'])
        if op=='_refund-claim':
            v=d['prepared'];r=next((r for r in self.all('refund') if r['request_key']==v['request_key']),None)
            if r:return r
            o=self.get(v['order'],'order');require(o['status'] in ('confirmed','review'),'Order no longer refundable.');require(not any(t['order']==o['ref'] and t['checked_in'] for t in self.all('ticket')),'Ticket has been admitted.');require(not any(r['order']==o['ref'] and r['status']!='failed' for r in self.all('refund')),'A refund already exists.')
            self.save('order',dict(status='refunding'),o)
            for t in self.all('ticket'):
                if t['order']==o['ref'] and t['status']=='valid':self.save('ticket',dict(status='refund_pending'),t)
            return self.save('refund',dict(v,status='pending'))
        r=next((r for r in self.all('refund') if r['request_key']==d['request_key']),None);require(r,'Refund not found.');p=d['provider'];require(str(p.get('PaymentId'))==r['payment_id'] and p.get('Amount')==r['amount'] and str(p.get('Currency','')).upper()==r['currency'] and p.get('IdempotencyKey')=='events-refund-'+r['request_key'],'Refund response does not match.');status=str(p.get('Status','')).lower();require(status in ('succeeded','pending','failed','submitting','reconciliation_required'),'Unknown refund state.')
        if r['status']=='succeeded':return r
        if status in ('succeeded','failed'):
            if status=='succeeded':require(p.get('RefundId'),'Refund ID missing.')
            o=self.get(r['order'],'order');self.save('order',dict(status='refunded' if status=='succeeded' else r['previous_status']),o)
            for t in self.all('ticket'):
                if t['order']==o['ref'] and t['status']=='refund_pending':self.save('ticket',dict(status='refunded' if status=='succeeded' else 'void' if self.get(o['event'],'event')['status']=='cancelled' else 'valid'),t)
            if status=='succeeded':self.mail(o,'Refund confirmed','Your event booking has been refunded. Admission tickets are no longer valid.','refunded-'+r['ref'])
        result=self.save('refund',dict(status=status,provider_id=p.get('RefundId','')),r);self.audit(result,'refund-'+status);return result

def plan(snapshot,request,identity=None,now=None,internal=False):
    e=Engine(snapshot,identity,now,internal);result=e.dispatch(request);writes=list(e.sql)
    for r in e.changed.values():writes.append('INSERT INTO entities(kind,ref,owner,version,data) VALUES('+','.join([q(r['kind']),q(r['ref']),q(r['owner']),str(r['version']),q(encoded(r))])+') ON CONFLICT(ref) DO UPDATE SET owner=excluded.owner,version=excluded.version,data=excluded.data;')
    sql=''
    if writes:sql='BEGIN IMMEDIATE; INSERT INTO write_guard(expected) VALUES('+q(e.settings.get('_revision','0'))+');\n'+'\n'.join(writes)+"\nUPDATE settings SET value=CAST(value AS INTEGER)+1 WHERE key='_revision'; DELETE FROM write_guard; COMMIT;\n"
    return sql+'SELECT '+q(encoded(result))+' AS result;',result

sql,result=plan(snapshot('AfterSend'),dict(obj('Send'),op='_mail-result'),internal=True)
return sql

